class AgentRecord(tuple):
    """Tuple-compatible record that also supports column-name access."""

    _columns = ("id", "codename", "status", "last_contact", "encrypted_message")

    def __new__(cls, values):
        """Create a new AgentRecord from a sequence of values."""
        return super().__new__(cls, tuple(values))

    def __getitem__(self, key):
        """Allow both integer index and column-name access."""
        if isinstance(key, str):
