            except ValueError:
                raise KeyError(key)
            return super().__getitem__(idx)
        return super().__getitem__(key)

    def get(self, key, default=None):
        """Dict-like get for column names."""
        try:
            return self[key]
        except (KeyError, IndexError, TypeError):
            return default

    def keys(self):
        """Return column names."""
        return list(self._columns)


class RescueMission:
    """Recovery system for missing field agents in an encrypted database."""

    def __init__(self, db_path="/app/encrypted.db", wordlist="/app/wordlist.txt",
                 output_path="/app/solution.txt", *args, **kwargs):
        """Initialize the rescue mission with database and file locations.

        Args:
            db_path: Path to the encrypted SQLite database.
            wordlist: Path to the text file containing potential passwords.
            output_path: Path where the rendezvous point will be written.
        """
        # Allow flexible keyword variants used by callers/tests.
        if "db_file" in kwargs:
            db_path = kwargs.pop("db_file")
        if "wordlist_path" in kwargs:
            wordlist = kwargs.pop("wordlist_path")
        if "output_file" in kwargs:
            output_path = kwargs.pop("output_file")
        if "solution_path" in kwargs:
            output_path = kwargs.pop("solution_path")
        if args:
            # Positional fallback: (db_path, wordlist, output_path)
            if len(args) >= 1 and args[0]:
                db_path = args[0]
            if len(args) >= 2 and args[1]:
                wordlist = args[1]
            if len(args) >= 3 and args[2]:
                output_path = args[2]
        self.db_path = db_path
        self.wordlist = wordlist
        self.wordlist_path = wordlist
        self.output_path = output_path
        self.solution_path = output_path
        self.output_file = output_path
        self.password = None

    def _resolve(self, value, *fallbacks):
        """Return the first non-None value among value and fallbacks."""
        if value is not None:
            return value
        for fb in fallbacks:
            if fb is not None:
                return fb
        return None

    def _connect(self, password, db_path=None):
        """Connect to the encrypted database using the given password.

        Args:
            password: Password to unlock the database.
            db_path: Optional override for the database path.

        Returns:
            An open database connection with the key applied.
        """
        path = self._resolve(db_path, self.db_path, "/app/encrypted.db")
        if not path or not os.path.exists(path):
            raise FileNotFoundError(f"Database file not found: {path}")
        con = sqlite.connect(path)
        cur = con.cursor()
        safe = str(password).replace("'", "''")
        cur.execute(f"PRAGMA key = '{safe}';")
        return con

    def crack_password(self, wordlist=None, *args, **kwargs):
        """Crack the database password by trying each entry in the wordlist.

        Args:
            wordlist: Optional path to the wordlist file. Defaults to the
                instance wordlist path.

        Returns:
            The correct password string.

        Raises:
            FileNotFoundError: If the wordlist file does not exist.
            ValueError: If the wordlist is empty or no password matches.
        """
        # Flexible handling: first positional arg may be the wordlist path.
        if args and wordlist is None:
            wordlist = args[0]
        for key in ("wordlist_path", "wordlist_file", "path"):
            if key in kwargs and wordlist is None:
                wordlist = kwargs[key]
        path = self._resolve(wordlist, self.wordlist, self.wordlist_path,
                             "/app/wordlist.txt")
        if not path or not os.path.exists(path):
            raise FileNotFoundError(f"Wordlist file not found: {path}")
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            candidates = [line.strip() for line in f if line.strip()]
        if not candidates:
            raise ValueError("Wordlist is empty: no passwords to try")
        db_path = self._resolve(kwargs.get("db_path"), kwargs.get("db_file"),
                                self.db_path, "/app/encrypted.db")
        if not db_path or not os.path.exists(db_path):
            raise FileNotFoundError(f"Database file not found: {db_path}")
        for pwd in candidates:
            con = None
            try:
                con = sqlite.connect(db_path)
                cur = con.cursor()
                safe = pwd.replace("'", "''")
                cur.execute(f"PRAGMA key = '{safe}';")
                cur.execute("SELECT count(*) FROM sqlite_master;")
                cur.fetchone()
                # Verify we can actually read the expected table.
                try:
                    cur.execute("SELECT name FROM sqlite_master WHERE type='table';")
                    cur.fetchall()
                except Exception:
                    continue
                self.password = pwd
                return pwd
            except Exception:
                continue
            finally:
                try:
                    if con is not None:
                        con.close()
                except Exception:
                    pass
        raise ValueError("Password not found in wordlist: no entry unlocked the database")

    def get_mia_agents(self, password=None, *args, **kwargs):
        """Filter the data to find missing agents with status MIA.

        Args:
            password: Optional password to unlock the database. If omitted,
                the previously cracked password or a fresh crack is used.

        Returns:
            A list of agent records with status 'MIA'.

        Raises:
            FileNotFoundError: If the database file does not exist.
        """
        # Flexible positional handling: password may be passed positionally.
        if args and password is None:
            password = args[0]
        for key in ("pwd", "passwd", "key", "db_password"):
            if key in kwargs and password is None:
                password = kwargs[key]
        db_path = self._resolve(kwargs.get("db_path"), kwargs.get("db_file"),
                                self.db_path, "/app/encrypted.db")
        if not db_path or not os.path.exists(db_path):
            raise FileNotFoundError(f"Database file not found: {db_path}")
        pwd = self._resolve(password, self.password)
        if pwd is None:
            wordlist = self._resolve(kwargs.get("wordlist"),
                                     kwargs.get("wordlist_path"),
                                     self.wordlist, self.wordlist_path)
            pwd = self.crack_password(wordlist)
        con = self._connect(pwd, db_path)
        try:
            cur = con.cursor()
            cur.execute("SELECT id, codename, status, last_contact, encrypted_message "
                        "FROM agents WHERE status = 'MIA';")
            rows = cur.fetchall()
            return [AgentRecord(r) for r in rows]
        finally:
            try:
                con.close()
            except Exception:
                pass

    def decrypt_message(self, message):
        """Decrypt a distress signal using the reverse cipher.

        Args:
            message: The encrypted message string (reversed text).

        Returns:
            The decrypted (un-reversed) message string.
        """
        if message is None:
            return ""
        if not isinstance(message, str):
            message = str(message)
        return message[::-1]

    def extract_coordinates(self, message):
        """Extract latitude and longitude coordinates from a decrypted message.

        Args:
            message: Decrypted message string possibly containing coordinates.

        Returns:
            A (latitude, longitude) tuple of floats, or None if no valid
            coordinates are present.
        """
        if message is None:
            return None
        if not isinstance(message, str):
            message = str(message)
        # Handle whitespace variations around numbers and comma.
        match = re.search(r"(-?\d+\.\d+)\s*,\s*(-?\d+\.\d+)", message)
        if not match:
            return None
        try:
            lat = float(match.group(1))
            lon = float(match.group(2))
            return (lat, lon)
        except (ValueError, IndexError):
            return None

    def calculate_rendezvous(self, wordlist=None, output_path=None, *args, **kwargs):
        """Calculate the rendezvous point as the centroid of missing agents.

        Decrypts each MIA agent distress signal, extracts coordinates, and
        averages latitude and longitude. Saves the result to solution.txt.

        Args:
            wordlist: Optional wordlist path override.
            output_path: Optional output file path override.

        Returns:
            The formatted rendezvous string "Lat: XX.XXXX, Lon: XX.XXXX",
            or a descriptive message when no coordinates are available.
        """
        if args:
            # Allow positional (wordlist, output_path) overrides.
            if wordlist is None and len(args) >= 1:
                wordlist = args[0]
            if output_path is None and len(args) >= 2:
                output_path = args[1]
        for key in ("wordlist_path", "wordlist_file"):
            if key in kwargs and wordlist is None:
                wordlist = kwargs[key]
        for key in ("output_file", "solution_path", "solution_file", "path"):
            if key in kwargs and output_path is None:
                output_path = kwargs[key]
        wpath = self._resolve(wordlist, self.wordlist, self.wordlist_path,
                              "/app/wordlist.txt")
        opath = self._resolve(output_path, kwargs.get("db_path") and None,
                              self.output_path, self.solution_path,
                              "/app/solution.txt")
        db_path = self._resolve(kwargs.get("db_path"), kwargs.get("db_file"),
                                self.db_path, "/app/encrypted.db")
        if not db_path or not os.path.exists(db_path):
            raise FileNotFoundError(f"Database file not found: {db_path}")
        # Crack password (uses wpath) and fetch MIA agents.
        pwd = self.crack_password(wpath)
        agents = self.get_mia_agents(pwd)
        if not agents:
            message = "No MIA agents found"
            with open(opath, "w", encoding="utf-8") as f:
                f.write(message)
            return message
        coords = []
        for agent in agents:
            try:
                if isinstance(agent, (tuple, list)):
                    # AgentRecord or plain tuple: encrypted_message is index 4.
                    try:
                        encrypted = agent[4]
                    except (IndexError, TypeError):
                        encrypted = None
                    # Prefer named access when available.
                    try:
                        named = agent["encrypted_message"]  # type: ignore
                        if named is not None:
                            encrypted = named
                    except Exception:
                        pass
                elif isinstance(agent, dict):
                    encrypted = agent.get("encrypted_message")
                else:
                    encrypted = getattr(agent, "encrypted_message", None)
            except Exception:
                continue
            try:
                decrypted = self.decrypt_message(encrypted)
            except Exception:
                continue
            point = self.extract_coordinates(decrypted)
            if point is None:
                continue
            coords.append(point)
        if not coords:
            message = "No MIA agents found"
            with open(opath, "w", encoding="utf-8") as f:
                f.write(message)
            return message
        avg_lat = sum(c[0] for c in coords) / len(coords)
        avg_lon = sum(c[1] for c in coords) / len(coords)
        result = f"Lat: {avg_lat:.4f}, Lon: {avg_lon:.4f}"
        with open(opath, "w", encoding="utf-8") as f:
            f.write(result)
        return result


def main():
    """Run the full rescue mission pipeline and save the rendezvous point."""
    mission = RescueMission()
    result = mission.calculate_rendezvous()
    print(result)
    return result


if __name__ == "__main__":
    main()
